update public.content_variants set body_id = $json${"type":"calculation","answer":"0.69","question":"Portofolio memiliki 50% saham (beta 1.2), 30% obligasi (beta 0.3), 20% uang tunai (beta 0). Apa itu portofolio beta?","difficulty":"beginner","parameters":{"hint":"Weight each asset's beta by its portfolio allocation."},"explanation":"Portofolio beta = (0,50 × 1,2) + (0,30 × 0,3) + (0,20 × 0) = 0,60 + 0,09 + 0 = 0,69."}$json$::jsonb where id = 'e62eb996-f99f-45aa-8611-b74696dae311';
